 private UsernamePasswordAuthenticationToken auth(boolean escribir,Long inst){var permisos=new ArrayList<>(List.of("EMPLEADO_LEER","EMPLEADO_LABORAL_LEER",escribir?"CONDICION_SALARIAL_ADMINISTRAR":"CONDICION_SALARIAL_LEER"));if(escribir)permisos.add("MOVIMIENTO_FINANCIERO_REGISTRAR");var a=permisos.stream().map(SimpleGrantedAuthority::new).toList();return new UsernamePasswordAuthenticationToken(new UsuarioPrincipal(inst,inst,Set.of(),true,false,"qa.etapa3","",a),"",a);}
 private void sesion(){SecurityContextHolder.getContext().setAuthentication(auth(true,420000L));}
 private MockHttpSession web(boolean escribir){var s=new MockHttpSession();s.setAttribute("SPRING_SECURITY_CONTEXT",new SecurityContextImpl(auth(escribir,420000L)));return s;}
 private FiltroNomina filtro(Long emp){return new FiltroNomina("","TODOS",null,null,null,null,emp,null,null,null,0,25);}
 private Long calendario(ProgramacionNominaService p,String codigo){var f=new CalendarioNominaForm();f.setCodigo(codigo);f.setNombre(codigo+" de prueba");f.setFrecuencia("MENSUAL");return p.guardarCalendario(null,f);}
 private Long periodo(ProgramacionNominaService p,Long cal,int mes){var c=p.contexto(cal);var f=new PeriodoNominaForm();f.setCalendarioId(cal);f.setCalendarioTexto(c.calendario());f.setCalendarioVersion(c.version());f.setCodigo("QA-2030-"+mes);f.setNombre("Periodo ficticio "+mes);f.setInicio(LocalDate.of(2030,mes,1));f.setFin(f.getInicio().withDayOfMonth(f.getInicio().lengthOfMonth()));f.setPago(f.getFin());f.setMotivo("Periodo ficticio para verificar generación");return p.guardarPeriodo(null,f);}
 private ConceptoPeriodoNominaForm ocasional(ConceptoPeriodoNominaService o,Long per,Long concepto,String importe){var c=o.contexto(420010L,concepto,per);var f=new ConceptoPeriodoNominaForm();f.setPeriodoId(per);f.setPeriodoTexto(c.periodo());f.setConceptoId(concepto);f.setConceptoTexto(c.concepto());f.setConceptoVersion(c.conceptoVersion());f.setLaboralVersion(c.laboralVersion());f.setCalendarioVersion(c.calendarioVersion());f.setSelloPeriodo(c.selloPeriodo());f.setImporte(new BigDecimal(importe));f.setMotivo("Concepto ficticio sólo del periodo elegido");return f;}
 private UUID seleccion(PreparacionNominaService s,Long periodo){var id=s.prepararPeriodo(periodo,"INDIVIDUAL");s.seleccionarPreparacion(id,0L,420010L,true);return id;}
