 private Long programacionActualizada(JdbcTemplate j,Long periodo){j.update("update periodo_nomina set nombre=nombre||' revisado',version=version+1 where id=?",periodo);return periodo;}
 private void probarLegacy(org.springframework.context.ConfigurableApplicationContext app,JdbcTemplate j,PreparacionNominaService s,ProgramacionNominaService p,Long periodo)throws Exception{
  var c=s.contexto(periodo);var ca=s.candidatos(periodo,filtro(420010L),"LISTO").getContent().getFirst();String oldPeriodo=j.queryForObject("select (cast(? as jsonb)-'regla_generacion')::text",String.class,c.fuentes());String oldEmpleado=j.queryForObject("select (cast(? as jsonb)-'calendario_empleado'-'ocasionales')::text",String.class,ca.fuentes()),sello=PreparacionNominaService.sello(oldPeriodo);
  Long id=j.queryForObject("insert into nomina_borrador(institucion_id,periodo_id,nombre,motivo_operacion,creado_por_id,actualizado_por_id) values(420000,?,'Borrador de regla anterior','Fixture legacy',420000,420000) returning id",Long.class,periodo);
  j.update("insert into nomina_borrador_revision(borrador_id,numero,institucion_id,periodo_id,periodo_codigo,periodo_nombre,calendario_id,calendario_texto,fecha_inicio,fecha_fin,fecha_pago,moneda,datos_periodo,sello_periodo,motivo,creado_por_id) values(?,1,420000,?,?,?,?,?,date '2030-01-01',date '2030-01-31',date '2030-01-31','MXN',cast(? as jsonb),?,'Fixture legacy',420000)",id,periodo,c.periodo().codigo(),c.periodo().nombre(),c.periodo().calendarioId(),c.calendario(),oldPeriodo,sello);
  j.update("insert into nomina_borrador_empleado(borrador_id,revision,institucion_id,periodo_id,empleado_id,empleado_codigo,empleado_nombre,fecha_inicio,fecha_fin,sueldo,percepciones,deducciones,aportaciones,propuesto,moneda,fuentes,sello) values(?,1,420000,?,420010,'EMP-ETAPA3-420010','Empleado Ficticio',date '2030-01-01',date '2030-01-31',12000,500,0,0,12500,'MXN',cast(? as jsonb),?)",id,periodo,oldEmpleado,PreparacionNominaService.sello(sello+oldEmpleado));
  assertThat(s.advertencia(s.obtener(id))).contains("regla de generación");assertThatThrownBy(()->s.bloquearParaAplicar(id,0L)).hasMessageContaining("periodo o calendario cambió");s.guardarPreparacion(s.prepararActualizacion(id),0L,null,"Adoptar regla nueva con revisión expresa");assertThat(s.obtener(id).revision()).isEqualTo(2);assertThat(s.guardados(id,1,0).getContent().getFirst().sello()).isEqualTo(PreparacionNominaService.sello(sello+oldEmpleado));assertThat(s.guardados(id,2,0).getContent().getFirst().sello()).isNotEqualTo(s.guardados(id,1,0).getContent().getFirst().sello());
 }
